import { readFile, readdir, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { rules } from '../src/rules/index.js';
import type { LintofuRuleDocs } from '../src/rules/types.js';

const CORE_CATEGORY = 'core';

const GENERATED_HEADER =
  '<!-- Generated by `npm run docs:rules`. Do not edit by hand. -->';

const CHECK_MARK = '✔';

const DOCS_RULES_DIR = 'docs/rules';

/** `docs/` is the vitepress source root, so rule pages route under `/rules`. */
const DOCS_RULES_DIR_ROUTE = 'rules';

/** Generated by this script, so it is not a rule page and has no rule. */
const RULE_INDEX_PAGE = 'index';

const RULE_INDEX_SIDEBAR_TEXT = 'All rules';

const MARKDOWN_EXTENSION = '.md';

const TABLE_COLUMNS = [
  'Rule',
  'Description',
  'Severity',
  'Category',
  'Recommended',
  'Fixable',
];

interface RuleWithDocs {
  meta?: { docs?: LintofuRuleDocs; fixable?: 'code' | 'whitespace' };
}

export interface RuleIndexEntry {
  name: string;
  description: string;
  severity: 'error' | 'warn';
  category: string;
  recommended: boolean;
  fixable: boolean;
}

export interface RuleCategoryGroup {
  category: string;
  entries: RuleIndexEntry[];
}

export interface RuleDocsPage {
  name: string;
  firstLine: string;
}

export interface RuleSidebarLink {
  text: string;
  link: string;
}

export interface RuleSidebarGroup {
  text: string;
  items: RuleSidebarLink[];
}

export type RuleSidebarEntry = RuleSidebarLink | RuleSidebarGroup;

export function toRuleIndexEntries(
  rules: Record<string, RuleWithDocs>,
): RuleIndexEntry[] {
  const entries: RuleIndexEntry[] = [];
  for (const [name, rule] of Object.entries(rules)) {
    const docs = rule.meta?.docs;
    entries.push({
      name,
      description: docs?.description ?? '',
      severity: docs?.severity ?? 'error',
      category: docs?.category ?? CORE_CATEGORY,
      recommended: docs?.recommended === true,
      fixable: rule.meta?.fixable !== undefined,
    });
  }
  return entries;
}

export function groupRulesByCategory(
  entries: readonly RuleIndexEntry[],
): RuleCategoryGroup[] {
  const byCategory = new Map<string, RuleIndexEntry[]>();
  for (const entry of entries) {
    const group = byCategory.get(entry.category);
    if (group) {
      group.push(entry);
    } else {
      byCategory.set(entry.category, [entry]);
    }
  }
  return [...byCategory]
    .map(([category, groupEntries]) => ({
      category,
      entries: [...groupEntries].sort((a, b) => a.name.localeCompare(b.name)),
    }))
    .sort((a, b) => compareCategories(a.category, b.category));
}

export function renderRuleIndex(entries: readonly RuleIndexEntry[]): string {
  const sections = groupRulesByCategory(entries).map((group) =>
    [
      `## ${group.category}`,
      '',
      `| ${TABLE_COLUMNS.join(' | ')} |`,
      `| ${TABLE_COLUMNS.map(() => '---').join(' | ')} |`,
      ...group.entries.map(renderRuleRow),
      '',
    ].join('\n'),
  );
  return [GENERATED_HEADER, '', '# Rules', '', ...sections].join('\n');
}

function renderRuleRow(entry: RuleIndexEntry): string {
  const cells = [
    `[\`${entry.name}\`](./${entry.name}.md)`,
    escapeTableCell(entry.description),
    entry.severity,
    entry.category,
    entry.recommended ? CHECK_MARK : '',
    entry.fixable ? CHECK_MARK : '',
  ];
  return `| ${cells.join(' | ')} |`;
}

function escapeTableCell(text: string): string {
  return text.replaceAll('|', '\\|');
}

export function findRuleDocsParityProblems(
  ruleNames: readonly string[],
  docsPageNames: readonly string[],
): string[] {
  const pages = new Set(docsPageNames);
  const names = new Set(ruleNames);
  const missingPages = ruleNames
    .filter((name) => !pages.has(name))
    .map(
      (name) =>
        `rule "${name}" has no docs page. expected ${DOCS_RULES_DIR}/${name}.md`,
    );
  const orphanPages = docsPageNames
    .filter((page) => page !== RULE_INDEX_PAGE && !names.has(page))
    .map(
      (page) =>
        `${DOCS_RULES_DIR}/${page}.md has no matching rule in src/rules/index.ts`,
    );
  return [...missingPages, ...orphanPages];
}

export function buildRuleSidebar(
  entries: readonly RuleIndexEntry[],
): RuleSidebarEntry[] {
  return [
    { text: RULE_INDEX_SIDEBAR_TEXT, link: `/${DOCS_RULES_DIR_ROUTE}/` },
    ...groupRulesByCategory(entries).map((group) => ({
      text: group.category,
      items: group.entries.map((entry) => ({
        text: entry.name,
        link: `/${DOCS_RULES_DIR_ROUTE}/${entry.name}`,
      })),
    })),
  ];
}

export function findRuleDocsHeadingProblems(
  pages: readonly RuleDocsPage[],
): string[] {
  return pages
    .filter((page) => page.firstLine !== `# ${page.name}`)
    .map(
      (page) =>
        `${DOCS_RULES_DIR}/${page.name}.md opens with "${page.firstLine}", expected "# ${page.name}"`,
    );
}

function compareCategories(a: string, b: string): number {
  if (a === b) return 0;
  if (a === CORE_CATEGORY) return -1;
  if (b === CORE_CATEGORY) return 1;
  return a.localeCompare(b);
}

async function readRuleDocsPages(pagesDir: string): Promise<RuleDocsPage[]> {
  const files = (await readdir(pagesDir)).filter((file) =>
    file.endsWith(MARKDOWN_EXTENSION),
  );
  return Promise.all(
    files.map(async (file) => ({
      name: file.slice(0, -MARKDOWN_EXTENSION.length),
      firstLine:
        (await readFile(join(pagesDir, file), 'utf8')).split('\n')[0] ?? '',
    })),
  );
}

const entryPoint = process.argv[1];
const isMain =
  entryPoint !== undefined &&
  import.meta.url === pathToFileURL(entryPoint).href;

if (isMain) {
  const root = join(dirname(fileURLToPath(import.meta.url)), '..');
  const pagesDir = join(root, DOCS_RULES_DIR);
  const pages = await readRuleDocsPages(pagesDir);
  const problems = [
    ...findRuleDocsParityProblems(
      Object.keys(rules),
      pages.map((page) => page.name),
    ),
    ...findRuleDocsHeadingProblems(
      pages.filter((page) => page.name !== RULE_INDEX_PAGE),
    ),
  ];
  if (problems.length > 0) {
    for (const problem of problems) {
      console.error(problem);
    }
    process.exit(1);
  }

  const indexPath = join(pagesDir, `${RULE_INDEX_PAGE}${MARKDOWN_EXTENSION}`);
  const current = await readFile(indexPath, 'utf8').catch(() => '');
  const rendered = renderRuleIndex(toRuleIndexEntries(rules));
  if (process.argv.includes('--check')) {
    if (rendered !== current) {
      console.error(
        `${DOCS_RULES_DIR}/${RULE_INDEX_PAGE}${MARKDOWN_EXTENSION} is stale. run: npm run docs:rules`,
      );
      process.exit(1);
    }
  } else if (rendered !== current) {
    await writeFile(indexPath, rendered);
  }
}
